// Правки по климатической сверке рекомендаций (отчёты reports/2026-09-10, 2026-09-11).
// Источники агропорогов препаратов — в reports/2026-09-11_sverka-rekomendaciy-klimat.md §2.1
// (веб-проверка: pogoda.yandex, antonovsad, masterasada, fertilizerdaily, ogorod.ru,
// direct.farm, agroxxi, syngenta).
//
// Запуск сухого прогона:   DRY=1 node add-klimat-sverka-fixes.js
// Запуск с записью в xlsx:       node add-klimat-sverka-fixes.js
// После записи — пересборка:     node build-from-xlsx.js

const path = require('path');
const XLSX = require('xlsx');

const XLSX_PATH = path.resolve(__dirname, '..', '..', 'garden-data.xlsx');
const DRY = !!process.env.DRY;
const SRC = 'reports/2026-09-11_sverka-rekomendaciy-klimat.md';

const MN = { yanvar:'ЯНВАРЬ', fevral:'ФЕВРАЛЬ', mart:'МАРТ', aprel:'АПРЕЛЬ', may:'МАЙ',
  iyun:'ИЮНЬ', iyul:'ИЮЛЬ', avgust:'АВГУСТ', sentyabr:'СЕНТЯБРЬ', oktyabr:'ОКТЯБРЬ',
  noyabr:'НОЯБРЬ', dekabr:'ДЕКАБРЬ' };

const wb = XLSX.readFile(XLSX_PATH);
let rows = XLSX.utils.sheet_to_json(wb.Sheets['Calendar'], { defval: '' });
const HEADERS = Object.keys(rows[0]);

const pk = r => [r.region, r.month, r.workType, r.plants, (r.text||'').slice(0,40)].join(' | ');
let log = [];

// --- helpers ------------------------------------------------------------------
function find({region, month, workType, plants, textEq, textIncludes}) {
  return rows.filter(r =>
    (region     === undefined || r.region   === region) &&
    (month      === undefined || r.month    === month) &&
    (workType   === undefined || r.workType === workType) &&
    (plants     === undefined || r.plants   === plants) &&
    (textEq     === undefined || r.text     === textEq) &&
    (textIncludes === undefined || String(r.text).includes(textIncludes)));
}
function expect(sel, n, tag) {
  const hit = find(sel);
  if (hit.length !== n) throw new Error(`[${tag}] ожидалось ${n}, найдено ${hit.length}\n` +
    hit.map(pk).join('\n'));
  return hit;
}
function setFields(sel, n, tag, patch) {
  const hit = expect(sel, n, tag);
  hit.forEach(r => {
    const before = {...r};
    Object.assign(r, typeof patch === 'function' ? patch(r) : patch);
    if (r.month && MN[r.month]) r.monthName = MN[r.month];
    log.push(`[${tag}] ${before.region}/${before.month}/${before.workType}\n  - ${JSON.stringify(before.text).slice(0,300)}\n  + ${JSON.stringify(r.text).slice(0,300)}` +
      (before.month!==r.month?`\n  month: ${before.month} -> ${r.month}`:'') +
      (before.workType!==r.workType?`\n  workType: ${before.workType} -> ${r.workType}`:'') +
      (before.plants!==r.plants?`\n  plants: ${before.plants} -> ${r.plants}`:''));
  });
}
function del(sel, n, tag) {
  const hit = expect(sel, n, tag);
  const set = new Set(hit);
  rows = rows.filter(r => !set.has(r));
  hit.forEach(r => log.push(`[${tag}] DELETE ${r.region}/${r.month}/${r.workType} — ${JSON.stringify(r.text).slice(0,200)}`));
}
function add(tag, list) {
  list.forEach(o => {
    const row = {};
    HEADERS.forEach(h => row[h] = o[h] !== undefined ? o[h] : '');
    row.monthName = MN[row.month] || row.monthName;
    row.source = row.source || SRC;
    rows.push(row);
    log.push(`[${tag}] ADD ${row.region}/${row.month}/${row.workType} [${row.plants}] — ${JSON.stringify(row.text).slice(0,200)}`);
  });
}

